// frontend/src/pages/S3Browser.js
// Browse real files in AWS S3 bucket — folder navigation, file list newest first, download via presigned URL

import { useState, useEffect, useCallback } from 'react';
import { s3BrowserAPI } from '../services/api';
import { Btn, Badge, Spinner, toast } from '../components/UI';

function fmtDate(s) {
  if (!s) return '—';
  return new Date(s).toLocaleString('en-IN', { day:'2-digit', month:'short', year:'numeric', hour:'2-digit', minute:'2-digit' });
}

function StorageClassBadge({ cls }) {
  const map = {
    STANDARD:         { bg:'var(--bv-blue-dim)',   tx:'var(--bv-blue)',   label:'STANDARD'     },
    STANDARD_IA:      { bg:'var(--bv-cyan-bg)',    tx:'var(--bv-cyan)',   label:'STANDARD-IA'  },
    ONEZONE_IA:       { bg:'var(--bv-cyan-bg)',    tx:'var(--bv-cyan)',   label:'ONEZONE-IA'   },
    GLACIER:          { bg:'var(--bv-purple-bg)',  tx:'var(--bv-purple)', label:'GLACIER'       },
    DEEP_ARCHIVE:     { bg:'var(--bv-purple-bg)',  tx:'var(--bv-purple)', label:'DEEP-ARCHIVE' },
    INTELLIGENT_TIERING:{ bg:'var(--bv-amber-bg)', tx:'var(--bv-amber)', label:'INT-TIERING'  },
  };
  const s = map[cls] || map.STANDARD_IA;
  return <span style={{ fontSize:10, padding:'2px 7px', borderRadius:8, fontWeight:600, background:s.bg, color:s.tx, flexShrink:0 }}>{s.label}</span>;
}

function FileIcon({ item }) {
  if (item.type === 'folder') return <i className="ti ti-folder-filled" style={{ fontSize:16, color:'var(--bv-amber)', flexShrink:0 }}/>;
  const n = (item.name||'').toLowerCase();
  if (n.endsWith('.sql.gz') || n.endsWith('.gz')) return <i className="ti ti-file-zip" style={{ fontSize:16, color:'var(--bv-cyan)', flexShrink:0 }}/>;
  if (n.endsWith('.sql'))   return <i className="ti ti-file-code"  style={{ fontSize:16, color:'var(--bv-blue)',   flexShrink:0 }}/>;
  if (n.endsWith('.rdb'))   return <i className="ti ti-database"   style={{ fontSize:16, color:'var(--bv-red)',    flexShrink:0 }}/>;
  return <i className="ti ti-file" style={{ fontSize:16, color:'var(--bv-txt3)', flexShrink:0 }}/>;
}

export default function S3Browser() {
  const [dests,       setDests]       = useState([]);
  const [selDest,     setSelDest]     = useState(null);
  const [prefix,      setPrefix]      = useState('');
  const [history,     setHistory]     = useState([]);
  const [data,        setData]        = useState(null);
  const [loading,     setLoading]     = useState(false);
  const [error,       setError]       = useState(null);
  const [errorCode,   setErrorCode]   = useState(null);
  const [filter,      setFilter]      = useState('');
  const [selFile,     setSelFile]     = useState(null);
  const [downloading, setDownloading] = useState(null);
  const [view,        setView]        = useState('browser'); // browser | analytics

  // Load S3 destinations
  useEffect(() => {
    s3BrowserAPI.destinations()
      .then(list => {
        setDests(list);
        if (list.length > 0) {
          setSelDest(list[0]);
          setPrefix(list[0].prefix || '');
        }
      })
      .catch(e => setError(e.message));
  }, []);

  const browse = useCallback(async (destId, browsePrefix) => {
    setLoading(true); setError(null); setErrorCode(null); setSelFile(null);
    try {
      const res = await s3BrowserAPI.list(destId, browsePrefix);
      setData(res);
      setPrefix(browsePrefix);
    } catch (e) {
      setError(e.message);
      setData(null);
    } finally { setLoading(false); }
  }, []);

  useEffect(() => {
    if (selDest) browse(selDest.id, selDest.prefix || '');
  }, [selDest, browse]);

  function navigateFolder(folder) {
    setHistory(h => [...h, prefix]);
    browse(selDest.id, folder.prefix);
  }

  function goBack() {
    if (!history.length) return;
    const prev = history[history.length - 1];
    setHistory(h => h.slice(0, -1));
    browse(selDest.id, prev);
  }

  function goRoot() {
    setHistory([]);
    browse(selDest.id, selDest.prefix || '');
  }

  function navigateBreadcrumb(segments, idx) {
    const target = segments.slice(0, idx + 1).join('/') + '/';
    setHistory(h => h.slice(0, idx));
    browse(selDest.id, target);
  }

  async function handleDownload(file) {
    setDownloading(file.key);
    try {
      const { url } = await s3BrowserAPI.presign(selDest.id, file.key);
      const a = document.createElement('a');
      a.href = url; a.target = '_blank'; a.rel = 'noopener noreferrer';
      a.download = file.name; document.body.appendChild(a); a.click(); document.body.removeChild(a);
      toast(`Downloading ${file.name} (link valid 1 hour)`);
    } catch (e) { toast(e.message, 'error'); }
    finally { setTimeout(() => setDownloading(null), 2000); }
  }

  // Breadcrumb from prefix
  const basePrefix = selDest?.prefix || '';
  const relPrefix  = prefix.startsWith(basePrefix) ? prefix.slice(basePrefix.length) : prefix;
  const breadcrumbs = relPrefix ? relPrefix.split('/').filter(Boolean) : [];

  const visible = [
    ...(data?.folders || []),
    ...(data?.files   || []),
  ].filter(item => !filter || item.name.toLowerCase().includes(filter.toLowerCase()));

  // ── NO DESTINATIONS ──────────────────────────────────────────────────────────
  if (!loading && dests.length === 0 && !error) {
    return (
      <div style={{ flex:1, display:'flex', flexDirection:'column', overflow:'hidden' }}>
        <Header dests={[]} selDest={null} onDest={()=>{}} onRefresh={null} filter="" setFilter={()=>{}} view={view} setView={setView} history={history} goBack={goBack}/>
        <div style={{ flex:1, display:'flex', alignItems:'center', justifyContent:'center', flexDirection:'column', gap:14, color:'var(--bv-txt3)' }}>
          <i className="ti ti-brand-aws" style={{ fontSize:56, color:'var(--bv-amber)' }}/>
          <div style={{ fontSize:17, fontWeight:500, color:'var(--bv-txt2)' }}>AWS S3 not configured</div>
          <div style={{ fontSize:13, textAlign:'center', lineHeight:1.8, maxWidth:420, color:'var(--bv-txt3)' }}>
            Go to <a href="/destinations" style={{ color:'var(--bv-blue)' }}>Destinations</a> → Add AWS S3 →<br/>
            Enter bucket name, access key, secret key → Save
          </div>
        </div>
      </div>
    );
  }

  return (
    <div style={{ flex:1, display:'flex', flexDirection:'column', overflow:'hidden' }}>
      <Header
        dests={dests} selDest={selDest} onDest={d => { setSelDest(d); setHistory([]); }}
        onRefresh={() => selDest && browse(selDest.id, prefix)}
        filter={filter} setFilter={setFilter}
        view={view} setView={setView}
        history={history} goBack={goBack}
      />

      {/* Bucket summary bar */}
      {data?.bucketStats && (
        <div style={{ padding:'7px 18px', background:'var(--bv-bg2)', borderBottom:'1px solid var(--bv-bd)',
          display:'flex', alignItems:'center', gap:20, flexShrink:0, flexWrap:'wrap' }}>
          <span style={{ fontSize:11, color:'var(--bv-txt3)' }}>
            <i className="ti ti-brand-aws" style={{ marginRight:5, color:'var(--bv-amber)' }}/>
            <strong style={{ color:'var(--bv-txt2)' }}>s3://{data.bucket}</strong>
          </span>
          <span style={{ fontSize:11, color:'var(--bv-txt3)' }}>
            Total size: <strong style={{ color:'var(--bv-txt2)' }}>{data.bucketStats.size}</strong>
          </span>
          {data.bucketStats.objects != null && (
            <span style={{ fontSize:11, color:'var(--bv-txt3)' }}>
              Objects: <strong style={{ color:'var(--bv-txt2)' }}>{data.bucketStats.objects.toLocaleString()}</strong>
            </span>
          )}
          <span style={{ fontSize:11, color:'var(--bv-txt3)' }}>
            Region: <strong style={{ color:'var(--bv-cyan)', fontFamily:'monospace' }}>{data.region}</strong>
          </span>
          {data.truncated && <span style={{ fontSize:10, color:'var(--bv-amber)' }}>⚠ Results truncated (500 limit)</span>}
        </div>
      )}

      {/* Breadcrumb toolbar */}
      <div style={{ padding:'8px 18px', borderBottom:'1px solid var(--bv-bd)', background:'var(--bv-bg2)',
        display:'flex', alignItems:'center', gap:6, flexShrink:0, flexWrap:'wrap' }}>
        <button onClick={goRoot} title="Go to bucket root"
          style={{ background:'none', border:'none', color:'var(--bv-amber)', cursor:'pointer', fontSize:15, padding:'2px 4px' }}>
          <i className="ti ti-brand-aws"/>
        </button>
        {basePrefix && (
          <>
            <span style={{ color:'var(--bv-bd2)', fontSize:12 }}>/</span>
            <button onClick={goRoot} style={{ background:'none', border:'none', color:'var(--bv-blue)',
              cursor:'pointer', fontSize:12, fontFamily:'monospace', padding:'2px 5px' }}>
              {basePrefix.replace(/\/$/, '')}
            </button>
          </>
        )}
        {breadcrumbs.map((seg, i) => (
          <span key={i} style={{ display:'flex', alignItems:'center', gap:3 }}>
            <span style={{ color:'var(--bv-bd2)', fontSize:12 }}>/</span>
            <button onClick={() => navigateBreadcrumb(breadcrumbs, i)} style={{
              background:'none', border:'none', cursor:'pointer', fontSize:12, padding:'2px 5px',
              fontFamily:'monospace', borderRadius:4,
              color: i === breadcrumbs.length-1 ? 'var(--bv-txt)' : 'var(--bv-blue)',
              fontWeight: i === breadcrumbs.length-1 ? 500 : 400,
            }}>{seg}</button>
          </span>
        ))}
        <div style={{ flex:1 }}/>
        <span style={{ fontSize:11, color:'var(--bv-txt3)' }}>
          {data ? `${(data.folders||[]).length} folders · ${(data.files||[]).length} files` : ''}
        </span>
      </div>

      {/* Main content */}
      <div style={{ flex:1, display:'flex', overflow:'hidden' }}>
        <div style={{ flex:1, display:'flex', flexDirection:'column', overflow:'hidden' }}>

          {/* Error state */}
          {error && (
            <div style={{ margin:16, padding:'13px 16px', background:'var(--bv-red-dim)',
              border:'1px solid var(--bv-red)', borderRadius:10, color:'var(--bv-red)', fontSize:13 }}>
              <i className="ti ti-alert-triangle" style={{ marginRight:8 }}/>
              {error}
              {errorCode === 'NOT_CONFIGURED' && (
                <div style={{ marginTop:8, fontSize:11, color:'var(--bv-txt2)' }}>
                  Configure S3 in <a href="/destinations" style={{ color:'var(--bv-blue)' }}>Destinations</a> with bucket name, access key, and secret key.
                </div>
              )}
              {errorCode === 'NO_AWSCLI' && (
                <div style={{ marginTop:8, fontFamily:'monospace', fontSize:11, color:'var(--bv-amber)',
                  background:'var(--bv-bg3)', padding:'6px 10px', borderRadius:6 }}>
                  pip3 install awscli --break-system-packages && pm2 restart backupvault
                </div>
              )}
              {errorCode === 'ACCESS_DENIED' && (
                <div style={{ marginTop:8, fontSize:11, color:'var(--bv-txt2)' }}>
                  Ensure your IAM user has: <code style={{ fontFamily:'monospace' }}>s3:ListBucket · s3:GetObject · s3:PutObject</code>
                </div>
              )}
            </div>
          )}

          {/* File table */}
          <div style={{ flex:1, overflowY:'auto' }}>
            {loading ? (
              <div style={{ display:'flex', justifyContent:'center', alignItems:'center', padding:60, gap:12, color:'var(--bv-txt3)' }}>
                <Spinner size={28}/> Fetching from S3...
              </div>
            ) : !error && (
              <table style={{ width:'100%', borderCollapse:'collapse' }}>
                <thead style={{ position:'sticky', top:0, background:'var(--bv-bg2)', zIndex:1 }}>
                  <tr>
                    {['Name','Size','Last Modified','Storage Class',''].map(h => (
                      <th key={h} style={{ textAlign:'left', fontSize:10, fontWeight:600, color:'var(--bv-txt3)',
                        letterSpacing:'.07em', textTransform:'uppercase', padding:'8px 16px',
                        borderBottom:'1px solid var(--bv-bd)', whiteSpace:'nowrap' }}>{h}</th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {visible.length === 0 && !loading ? (
                    <tr><td colSpan={5} style={{ textAlign:'center', padding:52, color:'var(--bv-txt3)', fontSize:13 }}>
                      {filter ? `No items matching "${filter}"` : 'Empty — no files in this path'}
                    </td></tr>
                  ) : visible.map(item => {
                    const isSel = selFile?.key === item.key;
                    return (
                      <tr key={item.key}
                        onClick={() => item.type === 'folder' ? navigateFolder(item) : setSelFile(item)}
                        style={{ cursor:'pointer', background: isSel ? 'var(--bv-blue-dim)' : '' }}
                        onMouseEnter={e => { if (!isSel) e.currentTarget.style.background = 'var(--bv-hover)'; }}
                        onMouseLeave={e => { if (!isSel) e.currentTarget.style.background = ''; }}>
                        <td style={{ padding:'9px 16px', borderBottom:'1px solid var(--bv-bd)' }}>
                          <div style={{ display:'flex', alignItems:'center', gap:9 }}>
                            <FileIcon item={item}/>
                            <span style={{ fontSize:12,
                              fontFamily: item.type==='file' ? 'monospace' : 'inherit',
                              color: item.type==='folder' ? 'var(--bv-amber)' : 'var(--bv-txt)' }}>
                              {item.name}{item.type === 'folder' ? '/' : ''}
                            </span>
                          </div>
                        </td>
                        <td style={{ padding:'9px 16px', borderBottom:'1px solid var(--bv-bd)',
                          fontSize:12, color:'var(--bv-txt2)', whiteSpace:'nowrap' }}>
                          {item.type === 'folder' ? '—' : item.sizeHuman}
                        </td>
                        <td style={{ padding:'9px 16px', borderBottom:'1px solid var(--bv-bd)',
                          fontSize:11, color:'var(--bv-txt3)', whiteSpace:'nowrap' }}>
                          {item.type === 'folder' ? '—' : fmtDate(item.lastModified)}
                        </td>
                        <td style={{ padding:'9px 16px', borderBottom:'1px solid var(--bv-bd)' }}>
                          {item.storageClass ? <StorageClassBadge cls={item.storageClass}/> : '—'}
                        </td>
                        <td style={{ padding:'9px 16px', borderBottom:'1px solid var(--bv-bd)' }}>
                          {item.type === 'file' && (
                            <button onClick={e => { e.stopPropagation(); handleDownload(item); }}
                              disabled={downloading === item.key}
                              style={{ background:'none', border:'1px solid var(--bv-bd2)',
                                color:'var(--bv-blue)', borderRadius:6, padding:'3px 10px',
                                fontSize:11, cursor:'pointer', display:'flex', alignItems:'center', gap:4 }}>
                              <i className={`ti ${downloading===item.key ? 'ti-loader' : 'ti-download'}`} style={{ fontSize:12 }}/>
                              {downloading === item.key ? 'Preparing...' : 'Download'}
                            </button>
                          )}
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            )}
          </div>

          {/* Status bar */}
          <div style={{ padding:'5px 16px', borderTop:'1px solid var(--bv-bd)', background:'var(--bv-bg2)',
            display:'flex', justifyContent:'space-between', fontSize:11, color:'var(--bv-txt3)', flexShrink:0 }}>
            <span>{visible.length} items{filter ? ` (filtered from ${(data?.folders||[]).length + (data?.files||[]).length})` : ''}</span>
            <span>
              {(data?.files||[]).length} files ·{' '}
              {(data?.folders||[]).length} folders ·{' '}
              s3://{data?.bucket}/{prefix}
            </span>
          </div>
        </div>

        {/* File detail panel */}
        {selFile && (
          <div style={{ width:260, flexShrink:0, borderLeft:'1px solid var(--bv-bd)',
            background:'var(--bv-bg2)', display:'flex', flexDirection:'column' }}>
            <div style={{ padding:'12px 14px', borderBottom:'1px solid var(--bv-bd)',
              display:'flex', justifyContent:'space-between', alignItems:'center' }}>
              <span style={{ fontSize:12, fontWeight:500, color:'var(--bv-txt)' }}>File details</span>
              <button onClick={() => setSelFile(null)} style={{ background:'none', border:'none',
                color:'var(--bv-txt3)', fontSize:18, cursor:'pointer', lineHeight:1 }}>×</button>
            </div>
            <div style={{ padding:14, flex:1, overflowY:'auto', display:'flex', flexDirection:'column', gap:10 }}>
              <div style={{ padding:'10px 12px', background:'var(--bv-bg3)', border:'1px solid var(--bv-bd)',
                borderRadius:8, textAlign:'center' }}>
                <i className="ti ti-file-zip" style={{ fontSize:34, color:'var(--bv-cyan)', display:'block', marginBottom:8 }}/>
                <div style={{ fontSize:11, fontFamily:'monospace', color:'var(--bv-txt)', wordBreak:'break-all', lineHeight:1.5 }}>
                  {selFile.name}
                </div>
              </div>
              {[
                ['Size',           selFile.sizeHuman],
                ['Last modified',  fmtDate(selFile.lastModified)],
                ['Storage class',  selFile.storageClass],
                ['ETag',           selFile.etag?.substring(0,16)+'…'],
                ['S3 key',         selFile.key],
              ].map(([k, v]) => v && (
                <div key={k}>
                  <div style={{ fontSize:10, color:'var(--bv-txt3)', letterSpacing:'.06em', textTransform:'uppercase', marginBottom:3 }}>{k}</div>
                  <div style={{ fontSize:11, color:'var(--bv-txt2)', fontFamily: k==='S3 key'||k==='ETag' ? 'monospace' : 'inherit', wordBreak:'break-all' }}>{v}</div>
                </div>
              ))}
              <button onClick={() => handleDownload(selFile)}
                disabled={downloading === selFile.key}
                style={{ width:'100%', padding:'9px', background:'var(--bv-accent)', color:'#fff',
                  border:'none', borderRadius:8, fontSize:13, cursor:'pointer', fontWeight:500,
                  display:'flex', alignItems:'center', justifyContent:'center', gap:6, marginTop:'auto' }}>
                <i className="ti ti-download" style={{ fontSize:15 }}/>
                {downloading === selFile.key ? 'Preparing link...' : 'Download file'}
              </button>
              <div style={{ fontSize:10, color:'var(--bv-txt3)', textAlign:'center' }}>
                Download via pre-signed URL (1 hour validity)
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

// ── PAGE HEADER ───────────────────────────────────────────────────────────────
function Header({ dests, selDest, onDest, onRefresh, filter, setFilter, view, setView, history, goBack }) {
  return (
    <div style={{ padding:'14px 20px 12px', borderBottom:'1px solid var(--bv-bd)',
      background:'var(--bv-bg2)', flexShrink:0 }}>
      <div style={{ display:'flex', alignItems:'flex-start', justifyContent:'space-between', gap:12 }}>
        <div>
          <div style={{ fontSize:20, fontWeight:500, color:'var(--bv-txt)', display:'flex', alignItems:'center', gap:9 }}>
            <i className="ti ti-brand-aws" style={{ color:'var(--bv-amber)', fontSize:22 }}/>
            AWS S3 Browser
          </div>
          <div style={{ fontSize:12, color:'var(--bv-txt2)', marginTop:3 }}>
            Browse backup files in S3 · ap-south-1 Mumbai ·{' '}
            {selDest ? <span style={{ color:'var(--bv-cyan)', fontFamily:'monospace' }}>s3://{selDest.bucket}</span> : 'No bucket configured'}
          </div>
        </div>
        <div style={{ display:'flex', gap:8, flexWrap:'wrap', alignItems:'center' }}>
          {dests.length > 1 && (
            <select value={selDest?.id || ''} onChange={e => onDest(dests.find(d => String(d.id)===e.target.value))}
              style={{ fontSize:12, padding:'6px 10px', background:'var(--bv-input)',
                border:'1px solid var(--bv-bd2)', color:'var(--bv-txt)', borderRadius:8 }}>
              {dests.map(d => <option key={d.id} value={d.id}>{d.name} · s3://{d.bucket}</option>)}
            </select>
          )}
          {history.length > 0 && (
            <button onClick={goBack} style={{ display:'flex', alignItems:'center', gap:5, padding:'6px 12px',
              border:'1px solid var(--bv-bd2)', background:'var(--bv-input)', color:'var(--bv-txt)',
              borderRadius:8, fontSize:12, cursor:'pointer' }}>
              <i className="ti ti-arrow-left" style={{ fontSize:13 }}/> Back
            </button>
          )}
          <input value={filter} onChange={e => setFilter(e.target.value)}
            placeholder="Filter files..."
            style={{ fontSize:12, padding:'6px 10px', background:'var(--bv-input)',
              border:'1px solid var(--bv-bd2)', color:'var(--bv-txt)', borderRadius:8, width:180 }}/>
          {onRefresh && (
            <button onClick={onRefresh} style={{ display:'flex', alignItems:'center', gap:5, padding:'6px 12px',
              border:'1px solid var(--bv-bd2)', background:'var(--bv-input)', color:'var(--bv-txt)',
              borderRadius:8, fontSize:12, cursor:'pointer' }}>
              <i className="ti ti-refresh" style={{ fontSize:13 }}/> Refresh
            </button>
          )}
        </div>
      </div>
    </div>
  );
}
